pub struct Solution;

impl Solution {
    pub fn jump(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        if n <= 1 {
            return 0;
        }

        let mut jumps = 0;
        let mut cur_end = 0;
        let mut max_reach = 0;

        for (i, &num) in nums.iter().enumerate().take(n - 1) {
            max_reach = max_reach.max(i + num as usize);
            if i == cur_end {
                jumps += 1;
                cur_end = max_reach;
            }
        }

        jumps
    }
}

